import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT_DIRECTORY = resolve(
  dirname(fileURLToPath(import.meta.url)),
  '..',
)
const CURRICULUM_SOURCE_FILE = resolve(
  ROOT_DIRECTORY,
  'config/high-math-curriculum.json',
)
const CATALOG_FILE = resolve(ROOT_DIRECTORY, 'config/owned-experiments.json')
const GENERATED_HEADER =
  '// Generated by scripts/generate-owned-experiment-registries.mjs. Do not edit.\n'
const SUPPORTED_INTENTS = [
  'visualize',
  'explain',
  'compare',
  'find-experiment',
]
const KNOWLEDGE_ALIASES = {
  '函数的定义域和值域': ['函数定义域', '函数值域', '函数的概念'],
  '函数图像': ['函数图形', '函数作图'],
  '数列趋近过程': ['数列极限', '数列的极限', '数列收敛'],
  '函数在某一点的极限': ['函数极限', '函数的极限', 'ε-δ极限定义', 'epsilon-delta'],
  '函数在无穷远处的极限': ['无穷远极限', '无穷极限'],
  '无穷小与无穷大': ['无穷小', '无穷大'],
  '极限的四则运算': ['极限运算法则', '极限的运算法则', '极限法则'],
  '函数在一点连续': ['连续的概念', '连续性'],
  '连续函数的性质': ['连续性质'],
  '导数的定义': ['导数概念'],
  '导数的几何意义': ['导数', '切线斜率', '瞬时变化率'],
  '微分的定义': ['微分'],
  '微分近似': ['线性近似', '函数增量'],
  '函数图像描绘': ['函数图形描绘', '函数作图', '导数作图'],
  '定积分定义': ['定积分'],
  '泰勒级数': ['泰勒公式', '麦克劳林公式'],
}

function unique(values) {
  return [...new Set(values)]
}

function normalizedIdentifier(value) {
  return value.replaceAll('-', ' ')
}

function validateCurriculum(curriculum) {
  if (!curriculum || !Array.isArray(curriculum.modules) || curriculum.modules.length !== 14) {
    throw new Error('High mathematics curriculum must contain exactly 14 modules.')
  }

  const pointCount = curriculum.modules.reduce(
    (total, module) => total + (Array.isArray(module.points) ? module.points.length : 0),
    0,
  )
  if (pointCount !== 150) {
    throw new Error(`High mathematics curriculum must contain exactly 150 points, received ${pointCount}.`)
  }
}

function buildExperiments(curriculum, descriptions) {
  return curriculum.modules.flatMap((module, moduleIndex) =>
    module.points.map((title, pointIndex) => {
      const id = `hm-${String(moduleIndex + 1).padStart(2, '0')}-${String(pointIndex + 1).padStart(2, '0')}`
      const description = descriptions[title]
      if (typeof description !== 'string' || !description.trim()) {
        throw new Error(`Missing semantic description for ${id}: ${title}`)
      }
      return {
        id,
        title,
        path: `/demo/${id}`,
        knowledgePointId: id,
        description: description.trim(),
        topics: [module.title, title],
        ownership: 'self-developed',
      }
    }),
  )
}

function validateExperiments(experiments) {
  if (!Array.isArray(experiments) || experiments.length !== 150) {
    throw new Error('Owned experiment catalog must contain exactly 150 entries.')
  }

  const ids = new Set()
  for (const experiment of experiments) {
    const requiredFields = [
      'id',
      'title',
      'path',
      'knowledgePointId',
      'description',
      'topics',
      'ownership',
    ]
    if (
      !experiment ||
      requiredFields.some((field) => !(field in experiment)) ||
      !Array.isArray(experiment.topics)
    ) {
      throw new Error('Each owned experiment must include every catalog field.')
    }
    if (ids.has(experiment.id)) {
      throw new Error(`Duplicate owned experiment ID: ${experiment.id}`)
    }
    if (experiment.path !== `/demo/${experiment.id}`) {
      throw new Error(`Invalid owned experiment path: ${experiment.path}`)
    }
    if (experiment.ownership !== 'self-developed') {
      throw new Error(`Invalid ownership for ${experiment.id}.`)
    }
    ids.add(experiment.id)
  }
}

function renderClientCurriculum(curriculum) {
  const modules = curriculum.modules.map((module, moduleIndex) => ({
    id: module.id,
    title: module.title,
    points: module.points.map((title, pointIndex) => ({
      id: `hm-${String(moduleIndex + 1).padStart(2, '0')}-${String(pointIndex + 1).padStart(2, '0')}`,
      title,
    })),
  }))

  return `${GENERATED_HEADER}
export interface HighMathCurriculumPoint {
  id: string
  title: string
}

export interface HighMathCurriculumModule {
  id: string
  title: string
  points: readonly HighMathCurriculumPoint[]
}

export const HIGH_MATH_COURSE_META = ${JSON.stringify({
    id: curriculum.courseId,
    title: curriculum.title,
    subtitle: curriculum.subtitle,
  }, null, 2)} as const

export const HIGH_MATH_CURRICULUM = ${JSON.stringify(modules, null, 2)} as const satisfies readonly HighMathCurriculumModule[]
`
}

function renderClientCatalog(experiments) {
  return `${GENERATED_HEADER}
export interface OwnedExperimentCatalogEntry {
  id: string
  title: string
  path: string
  knowledgePointId: string
  description: string
  topics: readonly string[]
  ownership: 'self-developed'
}

export const OWNED_EXPERIMENT_CATALOG = ${JSON.stringify(experiments, null, 2)} as const satisfies readonly OwnedExperimentCatalogEntry[]

export type OwnedExperimentId = typeof OWNED_EXPERIMENT_CATALOG[number]['id']
`
}

function routeMetadata(experiment) {
  return {
    semanticEnabled: true,
    aliases: unique([
      experiment.title,
      experiment.id,
      normalizedIdentifier(experiment.id),
      experiment.knowledgePointId,
      normalizedIdentifier(experiment.knowledgePointId),
      ...(KNOWLEDGE_ALIASES[experiment.title] ?? []),
    ]),
    strongPhrases: [experiment.description],
    keywords: unique([
      ...experiment.topics,
      normalizedIdentifier(experiment.knowledgePointId),
    ]),
    supportedIntents: SUPPORTED_INTENTS,
  }
}

function renderServerRegistry(experiments) {
  const registry = experiments.map((experiment) => ({
    ...experiment,
    ...routeMetadata(experiment),
  }))

  return `${GENERATED_HEADER}
import type { RoutableMathIntent } from './experimentRegistry.js'

export interface OwnedExperimentRouteDefinition {
  id: string
  title: string
  path: string
  knowledgePointId: string
  description: string
  topics: readonly string[]
  ownership: 'self-developed'
  semanticEnabled: boolean
  aliases: readonly string[]
  strongPhrases: readonly string[]
  keywords: readonly string[]
  supportedIntents: readonly RoutableMathIntent[]
}

export const OWNED_EXPERIMENT_REGISTRY = ${JSON.stringify(registry, null, 2)} as const satisfies readonly OwnedExperimentRouteDefinition[]
`
}

const curriculum = JSON.parse(await readFile(CURRICULUM_SOURCE_FILE, 'utf8'))
validateCurriculum(curriculum)
const descriptions = JSON.parse(await readFile(resolve(ROOT_DIRECTORY, 'config/experiment-descriptions.json'), 'utf8'))
const experiments = buildExperiments(curriculum, descriptions)
if (new Set(experiments.map(({ description }) => description)).size !== experiments.length) {
  throw new Error('Experiment semantic descriptions must not be duplicated.')
}
validateExperiments(experiments)

const sortedExperiments = [...experiments].sort((left, right) =>
  left.id.localeCompare(right.id),
)
const generatedFiles = new Map([
  [
    CATALOG_FILE,
    `${JSON.stringify(experiments, null, 2)}\n`,
  ],
  [
    resolve(ROOT_DIRECTORY, 'client/src/course/highMathCurriculum.generated.ts'),
    renderClientCurriculum(curriculum),
  ],
  [
    resolve(ROOT_DIRECTORY, 'server/src/content/highMathCurriculum.generated.ts'),
    renderClientCurriculum(curriculum),
  ],
  [
    resolve(ROOT_DIRECTORY, 'client/src/owned-experiments/catalog.generated.ts'),
    renderClientCatalog(sortedExperiments),
  ],
  [
    resolve(ROOT_DIRECTORY, 'server/src/agent/ownedExperimentRegistry.generated.ts'),
    renderServerRegistry(sortedExperiments),
  ],
])

const checkOnly = process.argv.includes('--check')
for (const [filePath, content] of generatedFiles) {
  let currentContent = null
  try {
    currentContent = await readFile(filePath, 'utf8')
  } catch (error) {
    if (error.code !== 'ENOENT') {
      throw error
    }
  }

  if (checkOnly) {
    if (currentContent !== content) {
      throw new Error(`Owned experiment registry is out of date: ${filePath}`)
    }
    continue
  }

  await mkdir(dirname(filePath), { recursive: true })
  await writeFile(filePath, content)
}

console.log(
  checkOnly
    ? 'Owned experiment registries are up to date.'
    : 'Owned experiment registries generated.',
)
